-- =====================================================================
--  031 — Skin cleansing study: collabs as brand content, and the
--        "What's behind this" panels
--
--  Updates the skin cleansing period now on the page (20 Jul to 18 Oct 2026):
--
--  1. Creator content made with a brand counts as the brand's voice, and the
--     conversation on it counts as earned. In this study that is the 13
--     collab posts on brand pages (no other creator content carried a
--     collab or disclosure tag, so it stays earned). Total share of voice,
--     engagement and sentiment do not change. Earned voice and "Who leads
--     earned conversation" change a little: Unilever's share of earned
--     conversation goes from 2.3% to 5.5%, mostly Pears and Lux collabs.
--  2. "Where each brand's voice comes from": brand pages, brand-backed
--     creators and earned, per brand.
--  3. A "What's behind this" panel for every chart and every brand: what it
--     shows, what drove it, what it means for each Unilever brand with a
--     next step, and translated consumer quotes with no names.
--
--  Run after 030. Safe to re-run: it replaces this period. Run 032 after it,
--  which adds the positive and negative voices to the panels.
-- =====================================================================

begin;

delete from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18';

values ('skin_cleansing', '2026-07-20', '2026-10-18', '20 Jul to 18 Oct 2026',
        '["Unilever brands hold 61.8% of skin cleansing share of voice. Lux leads at 34.2%, followed by Lifebuoy (14.7%) and Rani (14.1%).", "Unilever''s voice is mostly owned: brand content and the conversation it generates. In earned conversation, Unilever brands hold 5.5% of voice.", "Earned conversation is led by small home herbal sellers, with Sha Herbal''s Magic Soap at 44.4% and Thinu Soapy Co at 17.0%. Rani''s 11.1% earned voice is driven almost entirely by a viral \"Rani soap\" meme on social.", "Small sellers generate 56.1% of earned content in the category. 23.7% of consumer conversation is questions, mostly on price and how to buy. Price, fairness and glow, and herbal ingredients are the leading themes.", "Negative sentiment toward Lux and Lifebuoy is aimed mostly at their campaigns, the film tie-in and the Mister Sri Lanka pageant, not the products. Product complaints in the category are few, led by skin reactions linked to Calin."]'::jsonb);

  sentiment_positive, sentiment_neutral, sentiment_negative, share_facebook, share_instagram, share_tiktok) values
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'),
   'Lux', 0.34200, 0.33100, 0.32600, 0.06700, 0.01692,
   0.70500, 0.26100, 0.03400,
   0.28000, 0.46600, 0.23000),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'),
   'Lifebuoy', 0.14700, 0.16400, 0.20100, 0.03700, 0.00935,
   0.81200, 0.16100, 0.02700,
   0.02700, 0.23200, 0.12500),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'),
   'Pears', 0.12900, 0.12100, 0.07300, 0.11300, 0.02850,
   0.78800, 0.20700, 0.00500,
