  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'),
   'Velvet', 0.10700, 0.11900, 0.14900, 0.13800, 0.03473,
   0.81600, 0.16600, 0.01800,
   0.14200, 0.08500, 0.11100),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'),
