  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'),
   'Khomba', 0.06000, 0.04400, 0.05100, 0.10300, 0.02538,
   0.55300, 0.39700, 0.05000,
   0.13400, 0.00500, 0.07600),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'),
   'Champion', 0.03900, 0.04300, 0.01500, 0.00000, 0.00000,
