update sov_periods set cadence = 'study'
 where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18';



commit;

select p.label, p.is_published,
       (select count(*) from sov_panels s where s.period_id = p.period_id) as panels,
       (select round(sum(share_public) * 100, 1) from sov_brand_metrics m
         join sov_category_brands b on b.category_id = p.category_id and b.brand_name = m.brand_name
        where m.period_id = p.period_id and b.is_unilever) as unilever_earned_conversation_pct
  from sov_periods p
 where p.category_id = 'skin_cleansing' and p.period_start = '2026-07-20' and p.period_end = '2026-10-18';
