insert into sov_panels (period_id, panel_key, content) values
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'section:share', '{"read": "Unilever brands hold 61.8% of skin cleansing share of voice. Lux leads the category at 34.2%, with Lifebuoy at 14.7%, Rani at 14.1% and Pears at 12.9%.", "drivers": ["Unilever''s voice comes almost entirely from its own pages: brand pages account for 95.2% of Lux''s voice and 94.5% of Lifebuoy''s.", "Lux''s lead is built on activations and campaign content. Events and activations make up 36.9% of its brand content, and ambassador and celebrity talk is the top theme in its conversation at 27.5%.", "Rani reaches 14.1% almost without spending on brand content: 67.8% of its voice is earned, carried by a viral meme.", "Velvet holds 10.7% with a single clear message, softness, which is 85.9% of what its audience talks about."], "implications": {"Lux": {"implication": "Lux has the biggest voice in the category, but it is bought and owned rather than earned. Consumers rarely bring it up on their own.", "next_step": "Pair the next campaign burst with creator and consumer seeding that gives people a product reason to talk, not only the celebrity."}, "Lifebuoy": {"implication": "Lifebuoy holds second place, but nearly all of it is its own content and the reaction to it.", "next_step": "Build an always-on germ protection and freshness story between campaigns so the voice does not drop when activations end."}, "Pears": {"implication": "Pears is close behind Rani with a voice that is more earned than the other Unilever brands, at 19.0%.", "next_step": "Lean into the family and gentle care conversation that already exists around Pears, with parent creators rather than more giveaways."}}, "quotes": [{"text": "I use it too, it''s really good.", "translated": true, "kind": "praise"}, {"text": "Velvet really smells lovely, the pink one.", "translated": true, "kind": "praise"}, {"text": "Rani''s purple soap smells amazing too. The scent lasts until the bar is finished.", "translated": true, "kind": "praise"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'section:trend', '{"read": "Unilever brands held most of the weekly share of voice through August, peaking at 82.4%. From mid-September their share fell to between 31.6% and 47.7% as Rani and Khomba surged.", "drivers": ["Lux peaked at 63.9% of weekly share in early August on its film tie-in content and activations.", "Lifebuoy''s strongest week reached 44.7% in mid-August, during the Mister Sri Lanka campaign.", "Rani jumped to 49.5% of weekly share in mid-September when a meme about Rani soap spread on social.", "Khomba rose to 36.9% at the end of September on its NaturallyYou challenge, where contest entries make up 34.1% of its conversation."], "implications": {"Lux": {"implication": "Lux''s voice rises and falls with its campaigns. From mid-September it sat between 15.7% and 21.9% of weekly share.", "next_step": "Plan a steady base of content between bursts so share does not halve when a campaign ends."}, "Lifebuoy": {"implication": "Lifebuoy''s voice was concentrated around the pageant and faded to almost nothing by October.", "next_step": "Keep a lighter, regular presence after big activations rather than going quiet."}, "Pears": {"implication": "Pears was the steadiest Unilever brand and ended the period strongly, reaching 31.8% of weekly share in early October.", "next_step": "Use the momentum: keep the family care content regular and add a creator series to hold the gains."}}, "quotes": [{"text": "We watched it today. Lovely.", "translated": true, "kind": "praise"}, {"text": "Sad that you''re forced to promote a product, I guess you had no choice.", "translated": false, "kind": "complaint"}, {"text": "We don''t buy Rani, we buy Magic Soap.", "translated": true, "kind": "comparison"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'section:sentiment', '{"read": "Consumer conversation about every tracked brand is mostly positive. Velvet at 81.6% and Lifebuoy at 81.2% are the most positive; Champion at 41.9% and Rani at 47.9% the least, mainly because more of their conversation is neutral.", "drivers": ["Negativity is low across the board: Lux at 3.4% and Lifebuoy at 2.7% negative.", "Where people do give an opinion on Lux and Lifebuoy, most of the criticism is aimed at the campaigns, the film tie-in and the pageant, not the soap.", "Calin is the one brand where the criticism is about the product, mostly skin reactions.", "Velvet''s positive conversation centres on its scent and softness."], "implications": {"Lux": {"implication": "Lux is well liked at 70.5% positive, but the opinions people do voice are mostly about the film rather than the product.", "next_step": "Test campaign ideas with a small audience before launch, and keep a product proof point in every campaign piece."}, "Lifebuoy": {"implication": "Lifebuoy is liked, but the pageant drew sharp criticism of the contestants'' delivery and of creators who seemed forced to promote.", "next_step": "Choose ambassadors who genuinely use the product and let them speak in their own words."}, "Pears": {"implication": "Pears has almost no negative conversation, at 0.5%.", "next_step": "Protect it: keep claims about gentleness simple and well supported, since trust is its strength."}}, "quotes": [{"text": "The movie was a mix of a few Bollywood movies and the beginning was actually a joke. The plot twist at the end was a good one.", "translated": false, "kind": "complaint"}, {"text": "Why does the person who spoke first in the video have a fake Australian accent? Who did the PR for this?", "translated": false, "kind": "complaint"}, {"text": "Please don''t use Calin. All of us got a rash and suffered for months.", "translated": true, "kind": "complaint"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'section:public', '{"read": "Earned conversation in skin cleansing is led by small local herbal sellers, not the big brands. Sha Herbal''s Magic Soap holds 44.4% and Thinu Soapy Co 17.0%, while Unilever brands together hold 5.5%.", "drivers": ["Small sellers create 56.1% of category content outside brand pages and earn 50.1% of its engagement, mostly through direct selling with prices and ordering details.", "Questions make up 23.7% of consumer conversation, mostly how much and how to buy, which is exactly the conversation sellers invite.", "Rani''s 11.1% comes almost entirely from a single meme; without the meme, Sha Herbal''s lead rises to 49.3%.", "Pears is the strongest Unilever brand in earned conversation at 2.9%, ahead of Lux at 1.7%."], "implications": {"Lux": {"implication": "Lux is barely present in conversation it does not start itself, at 1.7%.", "next_step": "Seed product to creators and consumers in the herbal and glow space where the category conversation actually happens."}, "Lifebuoy": {"implication": "Lifebuoy hardly features in earned conversation, even though germ protection is a natural talking point.", "next_step": "Give people a reason to recommend it, for example everyday freshness content with real users rather than ambassadors."}, "Pears": {"implication": "Pears leads Unilever in earned conversation, mostly from parents.", "next_step": "Encourage parents to share their routines with Pears and answer their questions directly to grow this further."}}, "quotes": [{"text": "What''s the price? How do I get it?", "translated": true, "kind": "question"}, {"text": "We don''t buy Rani, we buy Magic Soap.", "translated": true, "kind": "comparison"}, {"text": "Chandanalepa is the best. I love its Ayurvedic, cinnamon, sandalwood and charcoal ones.", "translated": true, "kind": "praise"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'section:origin', '{"read": "Unilever''s voice is almost all its own: 95.2% of Lux''s and 94.5% of Lifebuoy''s comes from brand pages. Competitors such as Rani, Calin and Dettol rely far more on earned conversation.", "drivers": ["Brand-backed creator content is small: collabs make up 0.6% of Lux''s voice and 1.8% of Pears''. Under these rules a collab counts as the brand''s own, and the reaction to it counts as earned.", "Pears has the most earned voice of the Unilever brands at 19.0%.", "Rani''s voice is 67.8% earned, almost all of it from the meme.", "Champion''s voice is 100.0% from its own pages."], "implications": {"Lux": {"implication": "Lux''s size depends on how much it publishes. If it slows down, there is little earned conversation to keep it visible.", "next_step": "Set a target for the earned part of Lux''s voice and track it each month alongside total share."}, "Lifebuoy": {"implication": "Lifebuoy has the same dependence on its own content, with earned conversation at 5.5% of its voice.", "next_step": "Use collabs that invite people to respond, so the conversation around them counts as earned."}, "Pears": {"implication": "Pears already earns a fifth of its voice, the best balance in the Unilever portfolio.", "next_step": "Keep investing in the parent community that drives it."}}, "quotes": [{"text": "That''s my favourite body wash that I use on a daily basis.", "translated": false, "kind": "praise"}, {"text": "Velvet, you should know I''ve been your customer for about a decade.", "translated": false, "kind": "praise"}, {"text": "Rani''s purple soap smells amazing too. The scent lasts until the bar is finished.", "translated": true, "kind": "praise"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'section:topics', '{"read": "Price and value dominate category conversation at 38.9%, followed by fairness and glow at 16.6% and herbal and natural at 10.6%.", "drivers": ["The price conversation is mostly people asking sellers what a soap costs and how to order.", "Fairness and glow is driven by herbal sellers promising brighter skin.", "Herbal and natural is where local brands like Chandanalepa and Khomba compete, with herbal and natural making up 72.2% of what Khomba''s audience talks about.", "Problems such as acne at 5.6% are a smaller but specific need."], "implications": {"Lux": {"implication": "The themes Lux talks about, fragrance and celebrity, are not the ones the category is most interested in.", "next_step": "Bring value and skin benefits into Lux content, for example price per wash or visible results."}, "Lifebuoy": {"implication": "Germ protection and freshness are Lifebuoy''s ground, but they are not big themes in the category conversation.", "next_step": "Link hygiene to the problems people raise, such as acne and body odour, to make it more relevant."}, "Pears": {"implication": "Gentle care for babies and families is a small but loyal theme that Pears owns.", "next_step": "Extend it to gentle care for sensitive adult skin, where acne and dryness questions already appear."}}, "quotes": [{"text": "The soap is good. But the price going up month after month is the problem.", "translated": true, "kind": "complaint"}, {"text": "My pimples have really gone down a lot now.", "translated": true, "kind": "praise"}, {"text": "They call it a bleaching soap and then say it''s natural.", "translated": true, "kind": "complaint"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'section:intent', '{"read": "Almost half of consumer conversation, 48.2%, is simple reactions. Questions are next at 23.7% and praise at 18.7%; purchase intent is 3.2% and complaints 2.2%.", "drivers": ["Questions are mostly about price and where to buy, asked on seller and creator content.", "Praise is strongest for local herbal sellers and for Velvet''s scent.", "On Unilever pages the response is mostly reactions, for example 93.5% of Lifebuoy''s conversation and 94.3% of Pears''.", "Contest entries are a large part of the response to Lux and Khomba, at 10.9% and 34.1% of their conversation."], "implications": {"Lux": {"implication": "People react to Lux content but rarely ask about or recommend the product.", "next_step": "Add simple calls to action that start a product conversation, such as asking which variant people use."}, "Lifebuoy": {"implication": "Lifebuoy''s audience reacts but does not engage further.", "next_step": "Use questions and polls on freshness and hygiene to turn reactions into conversation."}, "Pears": {"implication": "Pears gets reactions and some recommendation requests from parents.", "next_step": "Answer those requests visibly so other parents see Pears recommended."}}, "quotes": [{"text": "How do I order?", "translated": true, "kind": "question"}, {"text": "What should you use for dry and normal skin?", "translated": true, "kind": "recommendation request"}, {"text": "Please make a soap for the bikini area and thighs. I''m really uncomfortable.", "translated": true, "kind": "recommendation request"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'section:source', '{"read": "Small sellers create 56.1% of category content outside brand pages, creators 29.4%, brands 6.7% and consumers 6.1%.", "drivers": ["Small sellers earn 50.1% of category engagement outside brand pages through direct selling, with prices and ordering details.", "Creators are the second source and the main way brands appear in earned conversation.", "Few consumers create content about the category on their own."], "implications": {"Lux": {"implication": "Most category content outside Lux''s pages comes from sellers and creators who do not feature Lux.", "next_step": "Work with the creators who already make skin care content, and give them a product angle rather than a campaign script."}, "Lifebuoy": {"implication": "Lifebuoy is largely absent from content created by others.", "next_step": "Partner with everyday creators on hygiene routines to appear where the category content is made."}, "Pears": {"implication": "Parents and creators talk about Pears more than any other Unilever brand outside its pages.", "next_step": "Support parent creators with product and ideas to multiply this."}}, "quotes": [{"text": "What''s the price? How do I get it?", "translated": true, "kind": "question"}, {"text": "My pimples have really gone down a lot now.", "translated": true, "kind": "praise"}, {"text": "In my personal experience it''s not good for the face. It made my face dry and my skin started to peel.", "translated": false, "kind": "complaint"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'brand:Lux', '{"read": "Lux leads skin cleansing with 34.2% of share of voice and 32.6% of engagement, and its audience sentiment is 70.5% positive.", "drivers": ["95.2% of Lux''s voice comes from its own pages; earned conversation is 4.3%.", "Events and activations make up 36.9% of its brand content, led by the film tie-in, and ambassador and celebrity is the top theme at 27.5%.", "Where people give an opinion, 52.9% is negative, mostly aimed at the film rather than the product.", "Giveaways and contests make up 10.1% of its brand content, and contest entries 10.9% of its conversation."], "implications": {"Lux": {"implication": "Lux is the most visible brand, but its voice depends on campaigns and is rarely about the product itself.", "next_step": "Keep the scale but rebalance content towards product benefits people ask about: fragrance, softness and value."}}, "quotes": [{"text": "You should be paid to watch the film. I feel I wasted my time watching it.", "translated": true, "kind": "complaint"}, {"text": "That''s my favourite body wash that I use on a daily basis.", "translated": false, "kind": "praise"}, {"text": "There are better imported brands than Lux, and those are what they actually use.", "translated": true, "kind": "comparison"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'brand:Lifebuoy', '{"read": "Lifebuoy holds 14.7% of share of voice and 20.1% of engagement, with audience sentiment 81.2% positive.", "drivers": ["94.5% of its voice comes from its own pages, much of it around the Mister Sri Lanka campaign, which drove its strongest week at 44.7%.", "Ambassador and celebrity is the top theme at 32.8%, ahead of freshness at 28.4% and germ protection at 20.9%.", "Where people give an opinion, 81.8% is negative, mostly about the pageant and the presenters rather than the soap.", "93.5% of the response to Lifebuoy is simple reactions."], "implications": {"Lifebuoy": {"implication": "The pageant gave Lifebuoy reach but little lasting conversation about the product, and it faded after the event.", "next_step": "Follow big activations with steady freshness and hygiene content featuring real users."}}, "quotes": [{"text": "Why does the person who spoke first in the video have a fake Australian accent? Who did the PR for this?", "translated": false, "kind": "complaint"}, {"text": "Sad that you''re forced to promote a product, I guess you had no choice.", "translated": false, "kind": "complaint"}, {"text": "I use baby soap. I''m not wasting money on that rubbish.", "translated": true, "kind": "comparison"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'brand:Pears', '{"read": "Pears holds 12.9% of share of voice and is the Unilever brand with the most earned voice, at 11.3% of earned conversation among tracked brands.", "drivers": ["19.0% of its voice is earned, and collabs add 1.8%.", "Family and kids at 48.0% and gentle care at 32.0% are what people talk about with Pears.", "Giveaways and contests make up 43.9% of its brand content.", "It has almost no negative conversation, at 0.5%."], "implications": {"Pears": {"implication": "Pears owns gentle family care and is talked about by parents, but almost half its brand content is giveaways.", "next_step": "Shift some of the giveaway budget into parent creators and useful baby care content."}}, "quotes": [{"text": "What should you use for dry and normal skin?", "translated": true, "kind": "recommendation request"}, {"text": "The old Pears baby cream was the best.", "translated": false, "kind": "comparison"}, {"text": "It is not clear how to enter this. More details please.", "translated": false, "kind": "question"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'brand:Rani', '{"read": "Rani holds 14.1% of share of voice, driven by earned conversation: 67.8% of its voice is earned.", "drivers": ["A viral meme about Rani soap carried its strongest week, at 49.5% of weekly share in mid-September.", "Fragrance is 52.9% of what its audience talks about.", "Its positive sentiment is lower than most at 47.9%, mainly because the meme conversation is neutral."], "implications": {"Lux": {"implication": "Rani shows how much voice a moment of popular culture can bring a soap brand.", "next_step": "Watch for cultural moments around Lux and respond quickly with light, shareable content."}, "Lifebuoy": {"implication": "Rani''s voice is not about hygiene, so it does not compete directly with Lifebuoy''s message.", "next_step": "Keep Lifebuoy''s focus on freshness and protection rather than chasing memes."}, "Pears": {"implication": "Rani''s fragrance story is far from Pears'' gentle care positioning.", "next_step": "No direct response needed; keep building the family care conversation."}}, "quotes": [{"text": "Rani''s purple soap smells amazing too. The scent lasts until the bar is finished.", "translated": true, "kind": "praise"}, {"text": "In the first days it had a lovely lavender scent, but now that scent is gone.", "translated": true, "kind": "complaint"}, {"text": "Why don''t you put it in the shops?", "translated": true, "kind": "complaint"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'brand:Velvet', '{"read": "Velvet holds 10.7% of share of voice and 14.9% of engagement, with the most positive audience at 81.6%.", "drivers": ["Softness is 85.9% of what its audience talks about, a single clear message.", "28.0% of its voice is earned, more than any Unilever brand.", "Fragrance is its other theme at 12.8%."], "implications": {"Lux": {"implication": "Velvet competes with Lux on softness and scent and wins on earned conversation.", "next_step": "Make softness a clearer, provable benefit in Lux content."}, "Lifebuoy": {"implication": "Velvet is not a hygiene brand and is not a direct threat to Lifebuoy''s positioning.", "next_step": "Keep watching it in the monthly read; no change needed now."}, "Pears": {"implication": "Velvet''s softness message overlaps with Pears'' gentle care.", "next_step": "Differentiate Pears on mildness for the whole family."}}, "quotes": [{"text": "If it''s not Velvet, there''s no point bathing.", "translated": true, "kind": "praise"}, {"text": "Velvet, you should know I''ve been your customer for about a decade.", "translated": false, "kind": "praise"}, {"text": "Velvet melts away quickly when you use it.", "translated": true, "kind": "complaint"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'brand:Khomba', '{"read": "Khomba holds 6.0% of share of voice, rising at the end of September to 36.9% of weekly share.", "drivers": ["Its NaturallyYou challenge drove the rise: contest entries make up 34.1% of its conversation and giveaways 42.9% of its brand content.", "Herbal and natural is 72.2% of what its audience talks about.", "37.4% of its voice is earned."], "implications": {"Lux": {"implication": "Khomba shows the pull of herbal positioning in this category.", "next_step": "Consider how Lux can speak to natural ingredients without losing its premium feel."}, "Lifebuoy": {"implication": "Khomba''s herbal protection story is close to Lifebuoy''s germ protection.", "next_step": "Bring natural ingredients into Lifebuoy''s protection message where the product supports it."}, "Pears": {"implication": "Khomba''s natural care appeals to families too.", "next_step": "Stress Pears'' gentle, trusted formula for children."}}, "quotes": [{"text": "Every day favourite.", "translated": false, "kind": "praise"}]}'::jsonb),
  ((select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18'), 'brand:Champion', '{"read": "Champion holds 3.9% of share of voice, all of it from its own pages.", "drivers": ["Its content focuses on germ protection, which is 26.0% of what its audience talks about.", "Its audience is the least positive at 41.9%, with more neutral conversation and some product complaints about the bar."], "implications": {"Lux": {"implication": "Champion is not a direct competitor to Lux.", "next_step": "Keep watching it in the monthly read; no change needed now."}, "Lifebuoy": {"implication": "Champion competes on germ protection, Lifebuoy''s own ground.", "next_step": "Keep Lifebuoy''s protection claims clear and simple so it stays the obvious choice."}, "Pears": {"implication": "Champion''s family hygiene message touches Pears'' family audience.", "next_step": "Keep Pears'' message on gentleness rather than germ protection."}}, "quotes": [{"text": "Most of them show the TFM value. Which one should we use?", "translated": true, "kind": "question"}, {"text": "Cut the watery feel and keep the bar the shape of the pack. Once unwrapped it has changed shape and is smaller, with water adding to the weight.", "translated": true, "kind": "complaint"}]}'::jsonb),
